import numpy as np

def kernel(x):
    result = []
    rows, cols = x.shape
    for i in range(0, rows, 128):
        for j in range(0, cols, 512):
            tile = x[i:i+128, j:j+512]
            # Compute running maximum over columns, starting from -inf
            running_max = np.full(tile.shape[0], -np.inf)
            for col in range(tile.shape[1]):
                running_max = np.maximum(running_max, tile[:, col])
            result.append(running_max)
    return np.concatenate(result)

